import{_ as l,C as c,o as n,c as s,j as d,a as e,E as o,a5 as r}from"./chunks/framework.CyyS6Zdm.js";const q=JSON.parse('{"title":"列表框","description":"","frontmatter":{},"headers":[],"relativePath":"components/listbox.md","filePath":"components/listbox.md","lastUpdated":1787173379000}'),h={name:"components/listbox.md"},b={id:"列表框",tabindex:"-1"};function x(p,t,u,m,g,f){const i=c("Badge"),a=c("XhDemo");return n(),s("div",null,[d("h1",b,[t[0]||(t[0]=e("列表框 ",-1)),o(i,{type:"info",text:"listbox"}),t[1]||(t[1]=e()),t[2]||(t[2]=d("a",{class:"header-anchor",href:"#列表框","aria-label":'Permalink to "列表框 <Badge type="info" text="listbox" />"'},"​",-1))]),t[3]||(t[3]=r('<p>一份直接铺在页面上的可选列表，不带浮层。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>选项需要常驻可见（穿梭框的两侧、设置面板的左栏）。</li><li>需要多选、范围选（Shift）与全选（Cmd + A）。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>选项要收起来：用<a href="./select">选择器</a>。</li><li>列表只是展示、不可选：用<a href="./list">列表</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>三种选择模式：单选、多选、以及带 Shift 范围扩展的模式。</li><li><code>typeahead</code> 连打检索。</li><li>定高滚动与空态都有对应部件。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="基础用法" tabindex="-1">基础用法 <a class="header-anchor" href="#基础用法" aria-label="Permalink to &quot;基础用法&quot;">​</a></h3><p>方向键只搬焦点，Enter 或空格才落值；整组只占一个 Tab 位</p>',10)),o(a,{src:"listbox/01-basic"}),t[4]||(t[4]=d("h3",{id:"多选",tabindex:"-1"},[e("多选 "),d("a",{class:"header-anchor",href:"#多选","aria-label":'Permalink to "多选"'},"​")],-1)),t[5]||(t[5]=d("p",null,"multiple 下空格改成切换该条，Shift + 方向键顺手扩选，Ctrl / Cmd + A 全选或全不选",-1)),o(a,{src:"listbox/02-multiple"}),t[6]||(t[6]=d("h3",{id:"分组",tabindex:"-1"},[e("分组 "),d("a",{class:"header-anchor",href:"#分组","aria-label":'Permalink to "分组"'},"​")],-1)),t[7]||(t[7]=d("p",null,"item-group 把条目分段，group-label 是这一段的可及名字，不参与选中也不接方向键",-1)),o(a,{src:"listbox/03-group"}),t[8]||(t[8]=d("h3",{id:"选择模式",tabindex:"-1"},[e("选择模式 "),d("a",{class:"header-anchor",href:"#选择模式","aria-label":'Permalink to "选择模式"'},"​")],-1)),t[9]||(t[9]=d("p",null,"selection-mode 直接指定三种模式，extended 是「单击换一条、Ctrl 与 Shift 才扩选」",-1)),o(a,{src:"listbox/04-selection-mode"}),t[10]||(t[10]=d("h3",{id:"弹出式选择",tabindex:"-1"},[e("弹出式选择 "),d("a",{class:"header-anchor",href:"#弹出式选择","aria-label":'Permalink to "弹出式选择"'},"​")],-1)),t[11]||(t[11]=d("p",null,"把列表装进浮层：触发器显示当前选中项，落值即收起，浮层底部还能放操作按钮",-1)),o(a,{src:"listbox/05-popover"}),t[12]||(t[12]=d("h3",{id:"定高滚动",tabindex:"-1"},[e("定高滚动 "),d("a",{class:"header-anchor",href:"#定高滚动","aria-label":'Permalink to "定高滚动"'},"​")],-1)),t[13]||(t[13]=d("p",null,"用 --xh-listbox-content-max-h 压住列表高度，条目多了就在容器里滚；方向键走到哪条，视图跟到哪条",-1)),o(a,{src:"listbox/06-scroll"}),t[14]||(t[14]=d("h3",{id:"空态",tabindex:"-1"},[e("空态 "),d("a",{class:"header-anchor",href:"#空态","aria-label":'Permalink to "空态"'},"​")],-1)),t[15]||(t[15]=d("p",null,"条目筛空时收起列表、亮出空态节点：它挂在 content 之外，方向键、连打检索与全选都看不见它",-1)),o(a,{src:"listbox/07-empty"}),t[16]||(t[16]=r('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-listbox&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhListboxContent</code> <code>XhListboxItem</code> <code>XhListboxItemGroup</code> <code>XhListboxItemGroupLabel</code> <code>XhListboxItemIndicator</code> <code>XhListboxItemText</code> <code>XhListboxLabel</code> <code>XhListboxRoot</code></td></tr><tr><td>组合式函数</td><td><code>useListbox</code></td></tr><tr><td>状态机</td><td><code>listboxMachine</code></td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/listbox.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;listbox&quot;</code>：<code>root</code> · <code>label</code> · <strong><code>content</code></strong> · <strong><code>item</code></strong> · <code>item-text</code> · <code>item-indicator</code> · <code>item-group</code> · <code>item-group-label</code></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>collection</code></td><td><code>ListboxNode[]</code></td><td></td><td>条目数据，显示文本与禁用的事实源。给了它，条目部件只需报 value。 缺省即回到「文本与禁用都写在条目部件上」的老路。</td></tr><tr><td><code>value</code></td><td><code>string | string[]</code></td><td></td><td>选中值，给定即受控；单选可写成裸串，内部归一成数组。</td></tr><tr><td><code>defaultValue</code></td><td><code>string | string[]</code></td><td></td><td></td></tr><tr><td><code>multiple</code></td><td><code>boolean</code></td><td></td><td>selectionMode=&#39;multiple&#39; 的简写；两者同时给时以 selectionMode 为准。</td></tr><tr><td><code>selectionMode</code></td><td><code>ListboxSelectionMode</code></td><td></td><td></td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td><td>整个列表禁用，键盘与点击都不再改选中值。</td></tr><tr><td><code>loop</code></td><td><code>boolean</code></td><td></td><td>方向键走到尽头是否回绕，默认 true。</td></tr><tr><td><code>dir</code></td><td><code>Direction</code></td><td></td><td>文字方向，默认 ltr。</td></tr><tr><td><code>orientation</code></td><td><code>Orientation</code></td><td></td><td>方向键轴向，默认 vertical。</td></tr><tr><td><code>typeahead</code></td><td><code>boolean</code></td><td></td><td>连打检索，默认开。</td></tr><tr><td><code>onValueChange</code></td><td><code>(details: ListboxValueChangeDetails) =&gt; void</code></td><td></td><td>value 变化意图回调。</td></tr></tbody></table><h2 id="事件" tabindex="-1">事件 <a class="header-anchor" href="#事件" aria-label="Permalink to &quot;事件&quot;">​</a></h2><p>自定义元素派发这些事件，Vue 组件对应同名 emit；载荷都在 <code>detail</code> 上。可双向绑定的值另有 <code>update:xxx</code>，见 Props。</p><table tabindex="0"><thead><tr><th>事件</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>value-change</code></td><td><code>ListboxValueChangeDetails</code></td><td>选中集合变化；detail 为 <code>{ value: string[] }</code></td></tr></tbody></table><h2 id="插槽" tabindex="-1">插槽 <a class="header-anchor" href="#插槽" aria-label="Permalink to &quot;插槽&quot;">​</a></h2><p>作者能拿到载荷的插槽。只转发内容、不带载荷的默认插槽不在此列——那类直接写子节点即可。</p><table tabindex="0"><thead><tr><th>Vue 组件</th><th>插槽</th><th>载荷</th><th>说明</th></tr></thead><tbody><tr><td><code>XhListboxRoot</code></td><td><code>default</code></td><td><code>ListboxRootSlotProps</code></td><td></td></tr><tr><td><code>XhListboxRoot</code></td><td><code>label</code></td><td>—</td><td></td></tr><tr><td><code>XhListboxRoot</code></td><td><code>item</code></td><td><code>ListboxNodeMeta</code></td><td></td></tr></tbody></table><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><p>状态机内部转移，写样式与业务都用不到；要监听变化请看上面的「事件」。</p><p><strong>状态</strong>：<code>idle</code></p><p><strong>事件</strong>：<code>VALUE.SET</code> · <code>ITEM.SELECT</code> · <code>ITEM.TOGGLE</code> · <code>ITEM.FOCUS</code> · <code>FOCUS.CLEAR</code> · <code>LIST.BLUR</code></p><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>useListbox</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>string[]</code></td><td>选中集合；单选模式下长度 ≤ 1。</td></tr><tr><td><code>collection</code></td><td><code>readonly ListboxNodeMeta[]</code></td><td>collection 推出的条目元信息，按数据顺序排列；没给 collection 即空数组。</td></tr><tr><td><code>selectionMode</code></td><td><code>ListboxSelectionMode</code></td><td>生效的选择模式。</td></tr><tr><td><code>focusedValue</code></td><td><code>string | null</code></td><td>焦点锚点；焦点不在列表内时为 null。</td></tr><tr><td><code>disabled</code></td><td><code>boolean</code></td><td></td></tr><tr><td><code>isSelected</code></td><td><code>(value: string) =&gt; boolean</code></td><td></td></tr><tr><td><code>setValue</code></td><td><code>(next: string[]) =&gt; void</code></td><td></td></tr><tr><td><code>select</code></td><td><code>(value: string) =&gt; void</code></td><td>只留这一个；加选用 toggle。</td></tr><tr><td><code>toggle</code></td><td><code>(value: string) =&gt; void</code></td><td></td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getLabelProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getContentProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemGroupProps</code></td><td><code>(props: ListboxItemGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemGroupLabelProps</code></td><td><code>(props: ListboxItemGroupProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemProps</code></td><td><code>(props: ListboxItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemTextProps</code></td><td><code>(props: ListboxItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr><tr><td><code>getItemIndicatorProps</code></td><td><code>(props: ListboxItemProps) =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/patterns/listbox/#keyboardinteraction" target="_blank" rel="noreferrer">W3C APG</a></p><table tabindex="0"><thead><tr><th>按键</th><th>生效条件</th><th>行为</th></tr></thead><tbody><tr><td><code>Tab</code> / <code>Shift+Tab</code></td><td>focus outside the listbox</td><td>整个列表只占一个 Tab 位：焦点进入锚点条目，无锚点时先落容器再由它转投</td></tr><tr><td><code>ArrowDown</code></td><td>focus in listbox, orientation=vertical</td><td>焦点移到下一个可停留条目（禁用项跳过、尽头按 loop 回绕）；orientation=horizontal 时改由 ArrowRight 承担，dir=rtl 再对调左右</td></tr><tr><td><code>ArrowUp</code></td><td>focus in listbox, orientation=vertical</td><td>焦点移到上一个可停留条目（禁用项跳过、尽头按 loop 回绕）；orientation=horizontal 时改由 ArrowLeft 承担，dir=rtl 再对调左右</td></tr><tr><td><code>Home</code></td><td>focus in listbox</td><td>焦点移到首个可停留条目</td></tr><tr><td><code>End</code></td><td>focus in listbox</td><td>焦点移到末个可停留条目</td></tr><tr><td><code>Enter</code> / <code>Space</code></td><td>focus on item, selectionMode 为 single 或 extended</td><td>只选中焦点条目，替换原有选中；条目自报禁用则不认</td></tr><tr><td><code>Space</code> / <code>Enter</code> / <code>Ctrl+Space</code></td><td>focus on item, 可多选（multiple；extended 下须按住 Ctrl/Cmd）</td><td>切换焦点条目的选中态，其余选中不动</td></tr><tr><td><code>Shift+ArrowDown</code> / <code>Shift+ArrowUp</code></td><td>focus in listbox, 可多选</td><td>焦点移到相邻条目并切换它的选中态；往回走即把刚扩进来的那个摘掉</td></tr><tr><td><code>Ctrl+A</code> / <code>Cmd+A</code></td><td>focus in listbox, 可多选</td><td>选中全部可选条目；已经全选则把它们一并取消（禁用但已选中的不动）</td></tr><tr><td><code>单个可打印字符</code></td><td>focus in listbox, typeahead 未关</td><td>连打检索把焦点移到首字母匹配的条目，不改选中值</td></tr></tbody></table><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>content</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-labelledby</code></td><td><code>label</code> 部件的 id</td></tr><tr><td><code>content</code></td><td><code>aria-multiselectable</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>content</code></td><td><code>aria-orientation</code></td><td>props.orientation</td></tr><tr><td><code>content</code></td><td><code>role</code></td><td>&#39;listbox&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-disabled</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>aria-selected</code></td><td>&#39;true&#39; | &#39;false&#39;</td></tr><tr><td><code>item</code></td><td><code>role</code></td><td>&#39;option&#39;</td></tr><tr><td><code>item-indicator</code></td><td><code>aria-hidden</code></td><td>&#39;true&#39;</td></tr><tr><td><code>item-group</code></td><td><code>aria-labelledby</code></td><td><code>group-label</code> 部件的 id</td></tr><tr><td><code>item-group</code></td><td><code>role</code></td><td>&#39;group&#39;</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/listbox.css</code> 按部件选择：<code>[data-scope=&quot;listbox&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>content</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>content</code></td><td><code>data-orientation</code></td><td>props.orientation</td></tr><tr><td><code>item-group</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>item-group-label</code></td><td><code>data-disabled</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-listbox-content-bg</code> · <code>--xh-listbox-content-border</code> · <code>--xh-listbox-content-fg</code> · <code>--xh-listbox-content-max-h</code> · <code>--xh-listbox-content-px</code> · <code>--xh-listbox-content-py</code> · <code>--xh-listbox-content-radius</code> · <code>--xh-listbox-gap</code> · <code>--xh-listbox-group-gap</code> · <code>--xh-listbox-group-label-fg</code> · <code>--xh-listbox-group-label-font-size</code> · <code>--xh-listbox-group-label-font-weight</code> · <code>--xh-listbox-group-label-px</code> · <code>--xh-listbox-group-label-py</code> · <code>--xh-listbox-item-bg-hover</code> · <code>--xh-listbox-item-fg</code> · <code>--xh-listbox-item-fg-selected</code> · <code>--xh-listbox-item-font-size</code> · <code>--xh-listbox-item-font-weight-selected</code> · <code>--xh-listbox-item-gap</code> · <code>--xh-listbox-item-indicator-fg</code> · <code>--xh-listbox-item-indicator-size</code> · <code>--xh-listbox-item-leading</code> · <code>--xh-listbox-item-px</code> · <code>--xh-listbox-item-py</code> · <code>--xh-listbox-item-radius</code> · <code>--xh-listbox-label-fg</code> · <code>--xh-listbox-label-font-size</code> · <code>--xh-listbox-label-font-weight</code></p><h2 id="动效" tabindex="-1">动效 <a class="header-anchor" href="#动效" aria-label="Permalink to &quot;动效&quot;">​</a></h2><p>状态切换走 <code>transition</code>。时长与缓动读<a href="./../guide/motion">动效令牌</a>，改令牌即改全局节奏。</p><p>系统开启减弱动效时由令牌层统一收敛，皮肤不另作判断。</p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>作为<a href="./transfer">穿梭框</a>、<a href="./popselect">弹出选择</a>的内层；长列表配<a href="./virtualizer">虚拟滚动</a>。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>多选时给出&quot;已选 N 项&quot;的回显，否则滚动后用户不知道选了多少。</li><li>定高，别让列表把页面撑到需要整页滚动。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>用它承载命令：列表框的条目是选项不是动作。</li><li>选项超过几百条却不虚拟化。</li></ul>',45))])}const L=l(h,[["render",x]]);export{q as __pageData,L as default};
